    "status": "ok",
    "sub_graphs": [
      {
        "id": "SG-TRIE-001",
        "name": "Trie Data Structures",
        "description": "Core data structures for the Merkle Patricia Trie: LeafNode, ExtensionNode, BranchNode, and the generic Trie container. Defines the node type union and type variables for key/value parameterization.",
        "invariants": [
          {
            "id": "INV-TRIE-001",
            "text": "EMPTY_TRIE_ROOT equals keccak256(RLP(b'')) = 0x56e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421."
          },
          {
            "id": "INV-TRIE-002",
            "text": "InternalNode is a union type: LeafNode | ExtensionNode | BranchNode. No other node types are valid."
          },
          {
            "id": "INV-TRIE-003",
            "text": "BranchNode.subnodes must always be a tuple of exactly 16 Extended elements (BranchSubnodes)."
          },
          {
            "id": "INV-TRIE-004",
            "text": "Node type union covers Account | Bytes | LegacyTransaction | Receipt | Uint | U256 | Withdrawal | None."
          }
        ],
        "functions": [],
        "data_structures": [
          {
            "id": "DS-TRIE-001",
            "name": "LeafNode",
            "type": "dataclass",
            "fields": [
              {"name": "rest_of_key", "type": "Bytes"},
              {"name": "value", "type": "Extended"}
            ],
            "description": "Leaf node in the Merkle Trie. Stores the remaining key suffix and the associated value."
          },
          {
            "id": "DS-TRIE-002",
            "name": "ExtensionNode",
            "type": "dataclass",
            "fields": [
              {"name": "key_segment", "type": "Bytes"},
              {"name": "subnode", "type": "Extended"}
            ],
            "description": "Extension node in the Merkle Trie. Compresses shared key prefixes into a single node."
          },
          {
            "id": "DS-TRIE-003",
            "name": "BranchNode",
            "type": "dataclass",
            "fields": [
              {"name": "subnodes", "type": "BranchSubnodes (Tuple of 16 Extended)"},
              {"name": "value", "type": "Extended"}
            ],
            "description": "Branch node in the Merkle Trie. Contains 16 subnodes (one per nibble) and an optional value."
          },
          {
            "id": "DS-TRIE-004",
            "name": "Trie",
            "type": "dataclass (Generic[K, V])",
            "fields": [
              {"name": "secured", "type": "bool"},
              {"name": "default", "type": "V"},
              {"name": "_data", "type": "Dict[K, V]"}
            ],
            "description": "The Merkle Trie container. Generic over key type K (bound to Bytes) and value type V. 'secured' flag indicates if keys are hashed before insertion."
          }
        ],
        "state_variables": [
          {
            "id": "SV-TRIE-001",
            "name": "EMPTY_TRIE_ROOT",
            "type": "Root",
            "description": "Constant root hash of an empty trie: keccak256(RLP(b''))."
          }
        ]
      },
      {
        "id": "SG-TRIE-002",
        "name": "Trie CRUD Operations",
        "description": "Core read/write operations on the Trie: trie_set, trie_get, and copy_trie. These form the public API for manipulating trie contents.",
        "invariants": [
          {
            "id": "INV-TRIE-005",
            "text": "trie_set with value == trie.default removes the key from _data (default values are represented by absence in the trie)."
          },
          {
            "id": "INV-TRIE-006",
            "text": "trie_get returns trie.default for any key not present in _data."
          },
          {
            "id": "INV-TRIE-007",
            "text": "For any key k and value v != trie.default: trie_set(trie, k, v) followed by trie_get(trie, k) returns v."
          },
          {
            "id": "INV-TRIE-008",
            "text": "copy_trie produces a shallow copy: modifications to the copy's _data dict do not affect the original (but frozen stored objects are shared)."
          }
        ],
        "functions": [
          {
            "id": "FN-TRIE-001",
            "signature": "trie_set(trie: Trie[K, V], key: K, value: V) -> None",
            "description": "Stores an item in the trie. Deletes the key if value equals trie.default.",
            "preconditions": ["trie is a valid Trie instance"],
            "postconditions": [
              "If value == trie.default: key is removed from trie._data",
              "If value != trie.default: trie._data[key] == value"
            ]
          },
          {
            "id": "FN-TRIE-002",
            "signature": "trie_get(trie: Trie[K, V], key: K) -> V",
            "description": "Gets an item from the trie. Returns trie.default if key is missing.",
            "preconditions": ["trie is a valid Trie instance"],
            "postconditions": [
              "Returns trie._data[key] if key in trie._data, else trie.default"
            ]
          },
          {
            "id": "FN-TRIE-003",
            "signature": "copy_trie(trie: Trie[K, V]) -> Trie[K, V]",
            "description": "Creates a shallow copy of the trie. Frozen stored objects are reused by reference.",
            "preconditions": ["trie is a valid Trie instance"],
            "postconditions": [
              "Returns a new Trie with same secured flag, default, and a shallow copy of _data"
            ]
          }
        ],
        "data_structures": [],
        "state_variables": []
      },
      {
        "id": "SG-TRIE-003",
        "name": "Node Encoding",
        "description": "Encoding functions that transform trie nodes into their RLP-serialized form for hashing. Includes encode_internal_node for internal MPT nodes and encode_node for typed value nodes.",
        "invariants": [
          {
            "id": "INV-TRIE-009",
            "text": "encode_internal_node(None) returns the RLP encoding of b'' (empty bytes)."
          },
          {
            "id": "INV-TRIE-010",
            "text": "If RLP-encoded node is < 32 bytes, encode_internal_node returns the unencoded (raw) form; otherwise it returns keccak256 of the encoded form."
          },
          {
            "id": "INV-TRIE-011",
            "text": "encode_node for Account type requires a non-None storage_root parameter."
          },
          {
            "id": "INV-TRIE-012",
            "text": "encode_node delegates to previous_trie.encode_node for unrecognized node types (fallback to Prague fork)."
          }
        ],
        "functions": [
          {
            "id": "FN-TRIE-004",
            "signature": "encode_internal_node(node: Optional[InternalNode]) -> Extended",
            "description": "Encodes a Merkle Trie node into RLP form. Returns raw form if encoded < 32 bytes, else keccak256 hash.",
            "preconditions": [
              "node is None, LeafNode, ExtensionNode, or BranchNode"
            ],
            "postconditions": [
              "If node is None: result is RLP-encodable as b''",
              "If encoded size < 32: returns unencoded tuple/list",
              "If encoded size >= 32: returns keccak256(encoded)"
            ]
          },
          {
            "id": "FN-TRIE-005",
            "signature": "encode_node(node: Node, storage_root: Optional[Bytes] = None) -> Bytes",
            "description": "Encode a typed Node for storage in the Merkle Trie. Dispatches based on node type.",
            "preconditions": [
              "If node is Account, storage_root must not be None"
            ],
            "postconditions": [
              "Returns RLP-encoded bytes representation of the node"
            ]
          }
        ],
        "data_structures": [],
        "state_variables": []
      },
      {
        "id": "SG-TRIE-004",
        "name": "Nibble Encoding",
        "description": "Nibble-level encoding utilities for the Hex-Prefix (HP) encoding used in Merkle Patricia Tries. Converts between byte arrays and nibble lists, and compresses nibble lists into compact form with leaf/extension flags.",
        "invariants": [
          {
            "id": "INV-TRIE-013",
            "text": "nibble_list_to_compact encodes the is_leaf flag in bit 1 of the high nibble of the first byte."
          },
          {
            "id": "INV-TRIE-014",
            "text": "nibble_list_to_compact encodes parity (odd/even length) in bit 0 of the high nibble of the first byte."
          },
          {
            "id": "INV-TRIE-015",
            "text": "bytes_to_nibble_list always produces output of exactly 2 * len(input) bytes, each in range [0, 15]."
          },
          {
            "id": "INV-TRIE-016",
            "text": "nibble_list_to_compact and bytes_to_nibble_list are used as a pair: bytes -> nibbles for key processing, nibbles -> compact for storage."
          }
        ],
        "functions": [
          {
            "id": "FN-TRIE-006",
            "signature": "nibble_list_to_compact(x: Bytes, is_leaf: bool) -> Bytes",
            "description": "Compresses a nibble-list into a standard byte array with HP encoding flags for leaf/extension distinction and parity.",
            "preconditions": [
              "All elements of x are in range [0, 15]"
            ],
            "postconditions": [
              "First byte encodes is_leaf flag and parity of nibble count",
              "Remaining bytes pack two nibbles each"
            ]
          },
          {
            "id": "FN-TRIE-007",
            "signature": "bytes_to_nibble_list(bytes_: Bytes) -> Bytes",
            "description": "Converts a byte array to a nibble list (each byte split into two nibbles).",
            "preconditions": ["bytes_ is a valid Bytes instance"],
            "postconditions": [
              "Output length is 2 * len(bytes_)",
              "Each output byte is in [0, 15]"
            ]
          }
        ],
        "data_structures": [],
        "state_variables": []
      },
      {
        "id": "SG-TRIE-005",
        "name": "Root Computation and Patricialize",
        "description": "Core Merkle Patricia Trie root computation. Prepares the trie data, recursively patricializes the key-value mapping into a tree of internal nodes, and computes the final root hash.",
        "invariants": [
          {
            "id": "INV-TRIE-017",
            "text": "root() of an empty trie (no entries in _data) returns EMPTY_TRIE_ROOT via encode_internal_node(None) -> keccak256(RLP(b''))."
          },
          {
            "id": "INV-TRIE-018",
            "text": "_prepare_trie hashes keys with keccak256 when trie.secured is True (secure trie mode)."
          },
          {
            "id": "INV-TRIE-019",
            "text": "_prepare_trie raises AssertionError if any encoded value is b'' (empty encoded values are invalid)."
          },
          {
            "id": "INV-TRIE-020",
            "text": "patricialize returns None for empty mappings, LeafNode for single-entry mappings, ExtensionNode when all keys share a common prefix at the current level, and BranchNode otherwise."
          },
          {
            "id": "INV-TRIE-021",
            "text": "In patricialize, Account, Receipt, and Uint values must not appear at branch-level internal nodes (only at leaf nodes)."
          },
          {
            "id": "INV-TRIE-022",
            "text": "The root hash is deterministic: the same set of key-value pairs always produces the same root regardless of insertion order."
          }
        ],
        "functions": [
          {
            "id": "FN-TRIE-008",
            "signature": "_prepare_trie(trie: Trie[K, V], get_storage_root: Optional[Callable[[Address], Root]] = None) -> Mapping[Bytes, Bytes]",
            "description": "Prepares trie for root calculation by encoding all values, optionally hashing keys (secured mode), and converting keys to nibble-list format.",
            "preconditions": [
              "If trie contains Account values, get_storage_root must not be None",
              "All encoded values must be non-empty"
            ],
            "postconditions": [
              "Returns mapping of nibble-encoded keys to RLP-encoded values",
              "If trie.secured: keys are keccak256(original_key) converted to nibbles",
              "If not trie.secured: keys are original keys converted to nibbles"
            ]
          },
          {
            "id": "FN-TRIE-009",
            "signature": "root(trie: Trie[K, V], get_storage_root: Optional[Callable[[Address], Root]] = None) -> Root",
            "description": "Computes the Merkle Patricia Trie root hash. Prepares trie data, patricializes into node tree, encodes root node, and returns final hash.",
            "preconditions": [
              "trie is a valid Trie instance",
              "If trie contains Account values, get_storage_root must be provided"
            ],
            "postconditions": [
              "Returns a 32-byte Root hash",
              "If encoded root < 32 bytes: returns keccak256 of RLP encoding",
              "If encoded root >= 32 bytes: returns the hash directly as Root"
            ]
          },
          {
            "id": "FN-TRIE-010",
            "signature": "patricialize(obj: Mapping[Bytes, Bytes], level: Uint) -> Optional[InternalNode]",
            "description": "Recursively builds the Merkle Patricia Trie structure from a flat key-value mapping. Chooses between LeafNode, ExtensionNode, and BranchNode based on key structure at each level.",
            "preconditions": [
              "Keys in obj are in nibble-list format",
              "level indicates current depth in the nibble key space"
            ],
            "postconditions": [
              "Returns None if obj is empty",
              "Returns LeafNode if obj has exactly one entry",
              "Returns ExtensionNode if all keys share a common prefix at current level",
              "Returns BranchNode with 16 subnodes otherwise"
            ]
          },
          {
            "id": "FN-TRIE-011",
            "signature": "common_prefix_length(a: Sequence, b: Sequence) -> int",
            "description": "Finds the length of the longest common prefix between two sequences.",
            "preconditions": ["a and b are valid sequences"],
            "postconditions": [
              "Returns int in range [0, min(len(a), len(b))]",
              "a[:result] == b[:result]"
            ]
          }
        ],
        "data_structures": [],
        "state_variables": []
      }
    ],
    "metadata": {
      "timestamp": "1770265501",
      "worker_id": 5,
      "iteration": 14,
      "total_subgraphs": 5,
      "total_invariants": 22,
      "total_functions": 11,
      "total_data_structures": 4,
      "extraction_method": "tree-sitter + manual analysis"
    }
  }
]

